package com.example.gdxgame;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.FileReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Properties;

import com.badlogic.gdx.ApplicationListener;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.files.FileHandle;
import com.badlogic.gdx.utils.I18NBundle;

public class I18NConsole implements ApplicationListener {

    private final String inputFile;
    private volatile boolean finished = false;
    private volatile int exitCode = 0;

    public I18NConsole(String inputFile) {
        this.inputFile = inputFile;
    }

    public boolean isFinished() {
        return finished;
    }

    public int getExitCode() {
        return exitCode;
    }

    private Properties loadProps(String path) throws Exception {
        Properties p = new Properties();
        try (InputStreamReader r = new InputStreamReader(new FileInputStream(path), StandardCharsets.UTF_8)) {
            p.load(r);
        }
        return p;
    }

    private String localeFilePath(String code) {
        if ("en".equals(code)) {
            return "i18n/Messages.properties";
        }
        return "i18n/Messages_" + code + ".properties";
    }

    @Override
    public void create() {
        FileHandle baseFile = Gdx.files.internal("i18n/Messages");
        Map<String, Properties> localeProps = new HashMap<>();
        Properties baseProps;
        try {
            baseProps = loadProps("assets/i18n/Messages.properties");
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            exitCode = 1;
            finished = true;
            return;
        }

        I18NBundle activeBundle = null;
        Properties activeProps = null;
        Properties activeLocaleProps = null;
        int localExit = 0;

        try (BufferedReader reader = new BufferedReader(new FileReader(inputFile))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String trimmed = line.trim();
                if (trimmed.isEmpty() || trimmed.startsWith("#")) {
                    continue;
                }
                String[] tokens = trimmed.split("\\s+");
                String cmd = tokens[0];

                if ("LOCALE".equals(cmd)) {
                    if (tokens.length < 2) {
                        System.err.println("Error: unsupported locale ");
                        localExit = 1;
                        break;
                    }
                    String code = tokens[1];
                    Locale locale;
                    switch (code) {
                        case "en":
                            locale = new Locale("en");
                            break;
                        case "fr":
                            locale = new Locale("fr");
                            break;
                        case "de":
                            locale = new Locale("de");
                            break;
                        default:
                            System.err.println("Error: unsupported locale " + code);
                            localExit = 1;
                            continue;
                    }
                    activeBundle = I18NBundle.createBundle(baseFile, locale);
                    if (!localeProps.containsKey(code)) {
                        try {
                            localeProps.put(code, loadProps("assets/" + localeFilePath(code)));
                        } catch (Exception ex) {
                            localeProps.put(code, new Properties());
                        }
                    }
                    activeProps = localeProps.get(code);
                    if ("en".equals(code)) {
                        activeLocaleProps = baseProps;
                    } else {
                        activeLocaleProps = localeProps.get(code);
                    }
                } else if ("GET".equals(cmd)) {
                    if (tokens.length < 2) {
                        System.err.println("Error: missing key ");
                        localExit = 1;
                        break;
                    }
                    String key = tokens[1];
                    if (activeBundle == null) {
                        System.err.println("Error: no locale selected");
                        localExit = 1;
                        break;
                    }
                    if (!activeLocaleProps.containsKey(key) && !baseProps.containsKey(key)) {
                        System.err.println("Error: missing key " + key);
                        localExit = 1;
                        break;
                    }
                    String value = activeBundle.get(key);
                    System.out.println(key + "=" + value);
                } else if ("FORMAT".equals(cmd)) {
                    if (tokens.length < 2) {
                        System.err.println("Error: missing key ");
                        localExit = 1;
                        break;
                    }
                    String key = tokens[1];
                    if (activeBundle == null) {
                        System.err.println("Error: no locale selected");
                        localExit = 1;
                        break;
                    }
                    if (!activeLocaleProps.containsKey(key) && !baseProps.containsKey(key)) {
                        System.err.println("Error: missing key " + key);
                        localExit = 1;
                        break;
                    }
                    int argCount = tokens.length - 2;
                    Object[] args = new Object[argCount];
                    for (int i = 0; i < argCount; i++) {
                        args[i] = tokens[2 + i];
                    }
                    String value = activeBundle.format(key, args);
                    System.out.println(key + "=" + value);
                } else {
                    System.err.println("Error: unknown command " + cmd);
                    localExit = 1;
                    break;
                }
            }
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
            localExit = 1;
        }

        exitCode = localExit;
        finished = true;
    }

    @Override
    public void render() {
    }

    @Override
    public void resize(int width, int height) {
    }

    @Override
    public void pause() {
    }

    @Override
    public void resume() {
    }

    @Override
    public void dispose() {
    }
}
